'use client';

import { useState, useRef } from 'react';
import { Button } from '@/components/ui/button';
import { Card } from '@/components/ui/card';
import { Camera, Upload, CheckCircle2, X } from 'lucide-react';
import { useCamera } from '@/hooks/mobile/useCamera';
import { SyncQueue } from '@/lib/offline/sync-queue';
import { toast } from 'sonner';
import { useRouter } from 'next/navigation';

export default function ProofOfDeliveryPage() {
  const router = useRouter();
  const videoRef = useRef<HTMLVideoElement>(null);
  const { stream, startCamera, stopCamera, captureImage } = useCamera();
  const [photo, setPhoto] = useState<string | null>(null);

  const handleStartCamera = async () => {
    await startCamera('environment');
    if (videoRef.current && stream) {
      videoRef.current.srcObject = stream;
    }
  };

  const handleCapture = () => {
    if (videoRef.current) {
      const img = captureImage(videoRef.current);
      if (img) setPhoto(img);
      stopCamera();
    }
  };

  const handleSubmit = async () => {
    if (!photo) return;

    try {
      if (!navigator.onLine) {
        await SyncQueue.addMutation({
          url: `/api/driver/loads/LD-84920/pod`,
          method: 'POST',
          body: { image: photo, timestamp: new Date().toISOString() },
        });
        toast.info('You are offline. POD saved and will sync automatically.');
      } else {
        toast.success('Proof of Delivery submitted successfully!');
      }
      router.push('/driver');
    } catch (e) {
      toast.error('Failed to submit POD');
    }
  };

  return (
    <div className="p-4 space-y-6">
      <div className="flex justify-between items-center">
        <h1 className="text-2xl font-bold text-slate-900 dark:text-slate-100">Proof of Delivery</h1>
        <Button variant="ghost" size="icon" onClick={() => router.push('/driver')}>
          <X className="h-5 w-5" />
        </Button>
      </div>

      <Card className="p-6 flex flex-col items-center justify-center min-h-[300px] border-dashed border-2 border-slate-300 dark:border-slate-700 bg-slate-50 dark:bg-slate-900/50">
        {!stream && !photo && (
          <div className="text-center space-y-4">
            <div className="bg-indigo-100 dark:bg-indigo-900/30 w-16 h-16 rounded-full flex items-center justify-center mx-auto text-indigo-600 dark:text-indigo-400">
              <Camera className="h-8 w-8" />
            </div>
            <p className="text-slate-500 font-medium">Take a photo of the signed BOL or delivered freight.</p>
            <Button onClick={handleStartCamera} className="w-full mt-4 bg-indigo-600 hover:bg-indigo-700 text-white">
              Open Camera
            </Button>
          </div>
        )}

        {stream && !photo && (
          <div className="relative w-full h-full flex flex-col items-center">
            <video 
              ref={videoRef} 
              autoPlay 
              playsInline 
              muted 
              className="w-full h-[300px] object-cover rounded-lg bg-black"
              // Fix for React strictly needing ref assignment after stream is ready
              onLoadedMetadata={() => videoRef.current?.play()}
            />
            <Button 
              onClick={handleCapture} 
              className="absolute bottom-4 h-14 w-14 rounded-full bg-white text-indigo-600 shadow-lg border-4 border-indigo-200 hover:bg-slate-100"
              size="icon"
            >
              <Camera className="h-6 w-6" />
            </Button>
          </div>
        )}

        {photo && (
          <div className="w-full space-y-4">
            <img src={photo} alt="POD Capture" className="w-full rounded-lg object-cover shadow-sm border border-slate-200 dark:border-slate-800" />
            <div className="flex gap-4">
              <Button variant="outline" className="flex-1" onClick={() => setPhoto(null)}>Retake</Button>
              <Button className="flex-1 bg-indigo-600 hover:bg-indigo-700 text-white gap-2" onClick={handleSubmit}>
                <Upload className="h-4 w-4" /> Submit
              </Button>
            </div>
          </div>
        )}
      </Card>
    </div>
  );
}

'use client';

import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import * as z from 'zod';
import { useRouter } from 'next/navigation';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { adminService } from '@/services/admin';
import { User, UserRole } from '@/types/admin';
import { toast } from 'sonner';

import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Save, X, ShieldAlert } from 'lucide-react';
import { 
  Select, 
  SelectContent, 
  SelectItem, 
  SelectTrigger, 
  SelectValue 
} from '@/components/ui/select';

const userFormSchema = z.object({
  firstName: z.string().min(2, 'First name is required'),
  lastName: z.string().min(2, 'Last name is required'),
  email: z.string().email('Invalid email address'),
  role: z.enum(['SUPER_ADMIN', 'ORG_ADMIN', 'OPERATIONS', 'FINANCE', 'SALES', 'DISPATCHER', 'VIEWER', 'DRIVER']),
  department: z.string().optional(),
  branch: z.string().optional(),
});

export type UserFormValues = z.infer<typeof userFormSchema>;

interface UserFormProps {
  initialData?: User;
  isEdit?: boolean;
}

export function UserForm({ initialData, isEdit }: UserFormProps) {
  const router = useRouter();
  const queryClient = useQueryClient();

  const { register, handleSubmit, setValue, watch, formState: { errors, isDirty } } = useForm<UserFormValues>({
    resolver: zodResolver(userFormSchema),
    defaultValues: initialData ? {
      firstName: initialData.firstName,
      lastName: initialData.lastName,
      email: initialData.email,
      role: initialData.role,
      department: initialData.department || '',
      branch: initialData.branch || '',
    } : {
      role: 'VIEWER',
    }
  });

  const mutation = useMutation({
    mutationFn: (data: UserFormValues) => {
      if (isEdit && initialData) {
        return adminService.updateUser(initialData.id, data);
      }
      return adminService.createUser(data);
    },
    onSuccess: () => {
      toast.success(isEdit ? 'User profile updated' : 'User invitation sent');
      queryClient.invalidateQueries({ queryKey: ['users'] });
      router.push('/admin/users');
    },
    onError: (err: any) => {
      toast.error(err.normalizedMessage || 'Failed to save user');
    }
  });

  const onSubmit = (data: UserFormValues) => mutation.mutate(data);

  return (
    <form onSubmit={handleSubmit(onSubmit)} className="space-y-8">

      <div className="bg-white dark:bg-gray-900 p-6 rounded-lg shadow-sm border border-gray-200 dark:border-gray-800">
        <h3 className="text-lg font-medium text-gray-900 dark:text-white mb-6 border-b border-gray-100 dark:border-gray-800 pb-3">Identity</h3>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="space-y-2">
            <Label>First Name</Label>
            <Input {...register('firstName')} />
            {errors.firstName && <p className="text-sm text-red-500">{errors.firstName.message}</p>}
          </div>
          <div className="space-y-2">
            <Label>Last Name</Label>
            <Input {...register('lastName')} />
            {errors.lastName && <p className="text-sm text-red-500">{errors.lastName.message}</p>}
          </div>
          <div className="space-y-2 md:col-span-2">
            <Label>Email Address</Label>
            <Input type="email" {...register('email')} disabled={isEdit} className={isEdit ? 'bg-gray-50 dark:bg-gray-800' : ''} />
            {errors.email && <p className="text-sm text-red-500">{errors.email.message}</p>}
            {isEdit && <p className="text-xs text-gray-500 mt-1">Email cannot be changed after invitation.</p>}
          </div>
        </div>
      </div>

      <div className="bg-white dark:bg-gray-900 p-6 rounded-lg shadow-sm border border-gray-200 dark:border-gray-800">
        <h3 className="text-lg font-medium text-gray-900 dark:text-white mb-6 border-b border-gray-100 dark:border-gray-800 pb-3">Access & RBAC</h3>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="space-y-2 md:col-span-2">
            <Label className="flex items-center gap-2">System Role <ShieldAlert className="h-4 w-4 text-blue-500" /></Label>
            <Select value={watch('role')} onValueChange={(v) => setValue('role', v as UserRole, { shouldDirty: true })}>
              <SelectTrigger><SelectValue placeholder="Select Role" /></SelectTrigger>
              <SelectContent>
                <SelectItem value="SUPER_ADMIN">Super Admin (Full Access)</SelectItem>
                <SelectItem value="ORG_ADMIN">Organization Admin</SelectItem>
                <SelectItem value="OPERATIONS">Operations Manager</SelectItem>
                <SelectItem value="FINANCE">Finance</SelectItem>
                <SelectItem value="SALES">Sales</SelectItem>
                <SelectItem value="DISPATCHER">Dispatcher</SelectItem>
                <SelectItem value="VIEWER">Viewer (Read Only)</SelectItem>
                <SelectItem value="DRIVER">Driver</SelectItem>
              </SelectContent>
            </Select>
            {errors.role && <p className="text-sm text-red-500">{errors.role.message}</p>}
          </div>
          <div className="space-y-2">
            <Label>Department (Optional)</Label>
            <Input {...register('department')} />
          </div>
          <div className="space-y-2">
            <Label>Branch/Location (Optional)</Label>
            <Input {...register('branch')} />
          </div>
        </div>
      </div>

      <div className="flex justify-end gap-4 pt-4">
        <Button type="button" variant="outline" onClick={() => router.back()}>
          <X className="mr-2 h-4 w-4" /> Cancel
        </Button>
        <Button type="submit" disabled={!isDirty || mutation.isPending}>
          <Save className="mr-2 h-4 w-4" /> {mutation.isPending ? 'Saving...' : isEdit ? 'Update Profile' : 'Send Invitation'}
        </Button>
      </div>
    </form>
  );
}

'use client';

import { useMemo } from 'react';
import { useRouter } from 'next/navigation';
import { User, AdminFilters } from '@/types/admin';
import {
  flexRender,
  getCoreRowModel,
  useReactTable,
  ColumnDef,
} from '@tanstack/react-table';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Lock, Unlock, ShieldAlert, Mail, MoreHorizontal, Edit, Trash2 } from 'lucide-react';
import { 
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";

interface UserTableProps {
  users: User[];
  total: number;
  isLoading: boolean;
  filters: AdminFilters;
  onFiltersChange: (filters: AdminFilters) => void;
  onLockUser: (id: string) => void;
  onResetPassword: (id: string) => void;
}

const getRoleBadge = (role: string) => {
  if (role.includes('ADMIN')) return <Badge className="bg-purple-100 text-purple-800 dark:bg-purple-900/50 dark:text-purple-300">Admin</Badge>;
  if (role === 'OPERATIONS' || role === 'DISPATCHER') return <Badge className="bg-blue-100 text-blue-800 dark:bg-blue-900/50 dark:text-blue-300">{role}</Badge>;
  if (role === 'FINANCE' || role === 'SALES') return <Badge className="bg-green-100 text-green-800 dark:bg-green-900/50 dark:text-green-300">{role}</Badge>;
  return <Badge variant="outline">{role}</Badge>;
};

export function UserTable({ users, total, isLoading, filters, onFiltersChange, onLockUser, onResetPassword }: UserTableProps) {
  const router = useRouter();

  const columns = useMemo<ColumnDef<User>[]>(
    () => [
      {
        id: 'name',
        header: 'User',
        cell: ({ row }) => (
          <div className="flex items-center gap-3">
            <div className="h-8 w-8 rounded-full bg-gray-100 dark:bg-gray-800 flex items-center justify-center font-semibold text-gray-600 dark:text-gray-300 border border-gray-200 dark:border-gray-700">
              {row.original.firstName.charAt(0)}{row.original.lastName.charAt(0)}
            </div>
            <div>
              <div className="font-medium text-gray-900 dark:text-white">
                {row.original.firstName} {row.original.lastName}
              </div>
              <div className="text-xs text-gray-500">{row.original.email}</div>
            </div>
          </div>
        ),
      },
      {
        accessorKey: 'role',
        header: 'Role',
        cell: ({ row }) => getRoleBadge(row.getValue('role')),
      },
      {
        accessorKey: 'department',
        header: 'Department',
        cell: ({ row }) => (
          <div className="text-sm text-gray-700 dark:text-gray-300">
            {row.getValue('department') || <span className="text-gray-400 italic">None</span>}
          </div>
        ),
      },
      {
        accessorKey: 'status',
        header: 'Status',
        cell: ({ row }) => {
          const status = row.getValue('status') as string;
          if (status === 'LOCKED') return <Badge variant="destructive"><Lock className="h-3 w-3 mr-1"/> Locked</Badge>;
          if (status === 'PENDING_INVITE') return <Badge variant="secondary"><Mail className="h-3 w-3 mr-1"/> Pending</Badge>;
          if (status === 'INACTIVE') return <Badge variant="outline">Inactive</Badge>;
          return <Badge className="bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200"><Unlock className="h-3 w-3 mr-1"/> Active</Badge>;
        },
      },
      {
        id: 'actions',
        header: '',
        cell: ({ row }) => (
          <div className="flex justify-end">
            <DropdownMenu>
              <DropdownMenuTrigger className="flex h-8 w-8 p-0 items-center justify-center rounded-md hover:bg-gray-100 transition-colors">
                <span className="sr-only">Open menu</span>
                <MoreHorizontal className="h-4 w-4" />
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end">
                <DropdownMenuLabel>Actions</DropdownMenuLabel>
                <DropdownMenuItem onClick={() => router.push(`/admin/users/${row.original.id}/edit`)}>
                  <Edit className="mr-2 h-4 w-4" /> Edit Profile
                </DropdownMenuItem>
                <DropdownMenuSeparator />
                <DropdownMenuItem onClick={() => onResetPassword(row.original.id)}>
                  <ShieldAlert className="mr-2 h-4 w-4" /> Force Password Reset
                </DropdownMenuItem>
                {row.original.status !== 'LOCKED' && (
                  <DropdownMenuItem onClick={() => onLockUser(row.original.id)} className="text-red-600 focus:text-red-600">
                    <Lock className="mr-2 h-4 w-4" /> Lock Account
                  </DropdownMenuItem>
                )}
              </DropdownMenuContent>
            </DropdownMenu>
          </div>
        ),
      }
    ],
    [router, onLockUser, onResetPassword]
  );

  const table = useReactTable({
    data: users,
    columns,
    getCoreRowModel: getCoreRowModel(),
    manualPagination: true,
    pageCount: Math.ceil(total / (filters.limit || 20)),
  });

  return (
    <div className="w-full">
      <div className="overflow-x-auto w-full">
        <table className="w-full text-sm text-left">
          <thead className="text-xs text-gray-500 uppercase bg-gray-50 dark:bg-gray-800 dark:text-gray-400 border-b border-gray-200 dark:border-gray-800">
            {table.getHeaderGroups().map((headerGroup) => (
              <tr key={headerGroup.id}>
                {headerGroup.headers.map((header) => (
                  <th key={header.id} className="px-4 py-3 whitespace-nowrap font-medium">
                    {flexRender(header.column.columnDef.header, header.getContext())}
                  </th>
                ))}
              </tr>
            ))}
          </thead>
          <tbody className="divide-y divide-gray-100 dark:divide-gray-800">
            {isLoading ? (
              Array.from({ length: 5 }).map((_, i) => (
                <tr key={i} className="animate-pulse">
                  <td className="px-4 py-4"><div className="flex items-center gap-3"><div className="h-8 w-8 bg-gray-200 dark:bg-gray-800 rounded-full"></div><div className="space-y-2"><div className="h-4 bg-gray-200 dark:bg-gray-800 rounded w-32"></div><div className="h-3 bg-gray-200 dark:bg-gray-800 rounded w-24"></div></div></div></td>
                  <td className="px-4 py-4"><div className="h-5 bg-gray-200 dark:bg-gray-800 rounded-full w-20"></div></td>
                  <td className="px-4 py-4"><div className="h-4 bg-gray-200 dark:bg-gray-800 rounded w-24"></div></td>
                  <td className="px-4 py-4"><div className="h-5 bg-gray-200 dark:bg-gray-800 rounded-full w-20"></div></td>
                  <td className="px-4 py-4"></td>
                </tr>
              ))
            ) : users.length === 0 ? (
              <tr>
                <td colSpan={columns.length} className="px-4 py-8 text-center text-gray-500">
                  No users found matching the criteria.
                </td>
              </tr>
            ) : (
              table.getRowModel().rows.map((row) => (
                <tr key={row.id} className="hover:bg-gray-50 dark:hover:bg-gray-800/50 transition-colors">
                  {row.getVisibleCells().map((cell) => (
                    <td key={cell.id} className="px-4 py-3">
                      {flexRender(cell.column.columnDef.cell, cell.getContext())}
                    </td>
                  ))}
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {/* Pagination */}
      <div className="flex items-center justify-between px-4 py-3 bg-white dark:bg-gray-900 border-t border-gray-200 dark:border-gray-800">
        <div className="flex-1 flex justify-between sm:hidden">
          <Button variant="outline" size="sm" onClick={() => onFiltersChange({ ...filters, page: Math.max(1, (filters.page || 1) - 1) })} disabled={(filters.page || 1) === 1}>Previous</Button>
          <Button variant="outline" size="sm" onClick={() => onFiltersChange({ ...filters, page: (filters.page || 1) + 1 })} disabled={(filters.page || 1) >= table.getPageCount()}>Next</Button>
        </div>
        <div className="hidden sm:flex-1 sm:flex sm:items-center sm:justify-between">
          <div>
            <p className="text-sm text-gray-700 dark:text-gray-400">
              Showing <span className="font-medium">{((filters.page || 1) - 1) * (filters.limit || 20) + (total > 0 ? 1 : 0)}</span> to <span className="font-medium">{Math.min((filters.page || 1) * (filters.limit || 20), total)}</span> of <span className="font-medium">{total}</span> users
            </p>
          </div>
          <div>
            <nav className="relative z-0 inline-flex rounded-md shadow-sm -space-x-px" aria-label="Pagination">
              <Button variant="outline" className="rounded-r-none" onClick={() => onFiltersChange({ ...filters, page: Math.max(1, (filters.page || 1) - 1) })} disabled={(filters.page || 1) === 1}>Previous</Button>
              <Button variant="outline" className="rounded-l-none" onClick={() => onFiltersChange({ ...filters, page: (filters.page || 1) + 1 })} disabled={(filters.page || 1) >= table.getPageCount()}>Next</Button>
            </nav>
          </div>
        </div>
      </div>
    </div>
  );
}

