'use client';

import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import * as z from 'zod';
import { useRouter } from 'next/navigation';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { fleetService } from '@/services/fleet';
import { Vehicle } from '@/types/fleet';
import { toast } from 'sonner';

import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { 
  Select, 
  SelectContent, 
  SelectItem, 
  SelectTrigger, 
  SelectValue 
} from '@/components/ui/select';
import { Save, X } from 'lucide-react';

const vehicleFormSchema = z.object({
  registrationNumber: z.string().min(1, 'Registration number is required'),
  type: z.enum(['TRUCK', 'VAN', 'TRAILER', 'MOTORCYCLE']),
  make: z.string().min(1, 'Make is required'),
  model: z.string().min(1, 'Model is required'),
  year: z.number().min(1990).max(new Date().getFullYear() + 1),
  capacity: z.number().min(0, 'Capacity must be positive'),
  axles: z.number().min(2),
  odometer: z.number().min(0),
});

export type VehicleFormValues = z.infer<typeof vehicleFormSchema>;

interface VehicleFormProps {
  initialData?: Vehicle;
  isEdit?: boolean;
}

export function VehicleForm({ initialData, isEdit }: VehicleFormProps) {
  const router = useRouter();
  const queryClient = useQueryClient();

  const { register, handleSubmit, setValue, watch, formState: { errors, isDirty } } = useForm<VehicleFormValues>({
    resolver: zodResolver(vehicleFormSchema),
    defaultValues: initialData ? {
      registrationNumber: initialData.registrationNumber,
      type: initialData.type,
      make: initialData.make,
      model: initialData.model,
      year: initialData.year,
      capacity: initialData.capacity,
      axles: initialData.axles,
      odometer: initialData.odometer,
    } : {
      year: new Date().getFullYear(),
      capacity: 0,
      axles: 2,
      odometer: 0,
      type: 'TRUCK'
    }
  });

  const selectedType = watch('type');

  const mutation = useMutation({
    mutationFn: (data: VehicleFormValues) => {
      if (isEdit && initialData) {
        return fleetService.updateVehicle(initialData.id, data);
      }
      return fleetService.createVehicle(data);
    },
    onSuccess: (data) => {
      toast.success(isEdit ? 'Vehicle updated' : 'Vehicle registered successfully');
      queryClient.invalidateQueries({ queryKey: ['fleet'] });
      router.push(`/fleet/${data.id}`);
    },
    onError: (err: any) => {
      toast.error(err.normalizedMessage || 'Failed to save vehicle');
    }
  });

  const onSubmit = (data: VehicleFormValues) => {
    mutation.mutate(data);
  };

  return (
    <form onSubmit={handleSubmit(onSubmit)} className="space-y-8 bg-white dark:bg-gray-900 p-6 rounded-lg shadow-sm border border-gray-200 dark:border-gray-800">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">

        {/* Core Identifiers */}
        <div className="space-y-4 md:col-span-2 border-b border-gray-200 dark:border-gray-800 pb-6">
          <h3 className="text-lg font-medium text-gray-900 dark:text-white">Registration & Specs</h3>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className="space-y-2">
              <Label htmlFor="registrationNumber">Registration Number</Label>
              <Input id="registrationNumber" {...register('registrationNumber')} className="uppercase" />
              {errors.registrationNumber && <p className="text-sm text-red-500">{errors.registrationNumber.message}</p>}
            </div>
            <div className="space-y-2">
              <Label>Vehicle Type</Label>
              <Select value={selectedType} onValueChange={(v: any) => setValue('type', v, { shouldDirty: true })}>
                <SelectTrigger>
                  <SelectValue placeholder="Select type" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="TRUCK">Truck</SelectItem>
                  <SelectItem value="VAN">Van</SelectItem>
                  <SelectItem value="TRAILER">Trailer</SelectItem>
                  <SelectItem value="MOTORCYCLE">Motorcycle</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label>Manufacturing Year</Label>
              <Input type="number" {...register('year', { valueAsNumber: true })} />
              {errors.year && <p className="text-sm text-red-500">{errors.year.message}</p>}
            </div>
          </div>
        </div>

        {/* Make / Model */}
        <div className="space-y-4">
          <h3 className="text-sm font-medium text-gray-500 uppercase tracking-wider">Manufacturer</h3>
          <div className="space-y-3">
            <div>
              <Label>Make</Label>
              <Input {...register('make')} placeholder="e.g. Volvo, Freightliner" />
              {errors.make && <p className="text-sm text-red-500">{errors.make.message}</p>}
            </div>
            <div>
              <Label>Model</Label>
              <Input {...register('model')} placeholder="e.g. VNL 860" />
              {errors.model && <p className="text-sm text-red-500">{errors.model.message}</p>}
            </div>
          </div>
        </div>

        {/* Dimensions & Usage */}
        <div className="space-y-4">
          <h3 className="text-sm font-medium text-gray-500 uppercase tracking-wider">Capabilities</h3>
          <div className="space-y-3">
            <div className="grid grid-cols-2 gap-3">
              <div>
                <Label>Capacity (kg)</Label>
                <Input type="number" {...register('capacity', { valueAsNumber: true })} />
              </div>
              <div>
                <Label>Axles</Label>
                <Input type="number" {...register('axles', { valueAsNumber: true })} />
              </div>
            </div>
            <div>
              <Label>Current Odometer</Label>
              <Input type="number" {...register('odometer', { valueAsNumber: true })} />
            </div>
          </div>
        </div>

      </div>

      <div className="flex justify-end gap-4 pt-4">
        <Button type="button" variant="outline" onClick={() => router.back()}>
          <X className="mr-2 h-4 w-4" /> Cancel
        </Button>
        <Button type="submit" disabled={!isDirty || mutation.isPending}>
          <Save className="mr-2 h-4 w-4" /> {mutation.isPending ? 'Saving...' : 'Save Vehicle'}
        </Button>
      </div>
    </form>
  );
}

'use client';

import { useMemo } from 'react';
import { useRouter } from 'next/navigation';
import { Vehicle, FleetFilters } from '@/types/fleet';
import {
  flexRender,
  getCoreRowModel,
  useReactTable,
  ColumnDef,
} from '@tanstack/react-table';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Truck, AlertTriangle, Wrench, CheckCircle2 } from 'lucide-react';

interface VehicleTableProps {
  vehicles: Vehicle[];
  total: number;
  isLoading: boolean;
  filters: FleetFilters;
  onFiltersChange: (filters: FleetFilters) => void;
}

const getStatusBadge = (status: Vehicle['status']) => {
  switch (status) {
    case 'AVAILABLE':
      return <Badge className="bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200"><CheckCircle2 className="mr-1 h-3 w-3" /> Available</Badge>;
    case 'IN_USE':
      return <Badge className="bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-200"><Truck className="mr-1 h-3 w-3" /> In Use</Badge>;
    case 'MAINTENANCE':
      return <Badge className="bg-orange-100 text-orange-800 dark:bg-orange-900 dark:text-orange-200"><Wrench className="mr-1 h-3 w-3" /> Maintenance</Badge>;
    case 'OUT_OF_SERVICE':
      return <Badge variant="destructive"><AlertTriangle className="mr-1 h-3 w-3" /> Out of Service</Badge>;
    default:
      return <Badge variant="secondary">{status}</Badge>;
  }
};

export function VehicleTable({ vehicles, total, isLoading, filters, onFiltersChange }: VehicleTableProps) {
  const router = useRouter();

  const columns = useMemo<ColumnDef<Vehicle>[]>(
    () => [
      {
        accessorKey: 'registrationNumber',
        header: 'Registration #',
        cell: ({ row }) => (
          <div className="font-medium text-blue-600 dark:text-blue-400">
            {row.getValue('registrationNumber')}
          </div>
        ),
      },
      {
        accessorKey: 'type',
        header: 'Type',
        cell: ({ row }) => <span className="capitalize">{row.getValue<string>('type').toLowerCase()}</span>,
      },
      {
        accessorKey: 'status',
        header: 'Status',
        cell: ({ row }) => getStatusBadge(row.getValue('status')),
      },
      {
        accessorKey: 'odometer',
        header: 'Odometer (mi)',
        cell: ({ row }) => <span className="text-sm text-gray-500">{row.getValue<number>('odometer').toLocaleString()}</span>,
      },
      {
        accessorKey: 'fuelLevel',
        header: 'Fuel / Battery',
        cell: ({ row }) => {
          const fuel = row.getValue<number>('fuelLevel');
          const color = fuel < 20 ? 'bg-red-500' : fuel < 50 ? 'bg-orange-500' : 'bg-green-500';
          return (
            <div className="flex items-center gap-2">
              <div className="w-16 h-2 bg-gray-200 dark:bg-gray-700 rounded-full overflow-hidden">
                <div className={`h-full ${color}`} style={{ width: `${fuel}%` }}></div>
              </div>
              <span className="text-xs text-gray-500">{fuel}%</span>
            </div>
          );
        },
      }
    ],
    []
  );

  const table = useReactTable({
    data: vehicles,
    columns,
    getCoreRowModel: getCoreRowModel(),
    manualPagination: true,
    pageCount: Math.ceil(total / (filters.limit || 20)),
  });

  return (
    <div className="w-full">
      <div className="overflow-x-auto w-full">
        <table className="w-full text-sm text-left">
          <thead className="text-xs text-gray-500 uppercase bg-gray-50 dark:bg-gray-800 dark:text-gray-400 border-b border-gray-200 dark:border-gray-800">
            {table.getHeaderGroups().map((headerGroup) => (
              <tr key={headerGroup.id}>
                {headerGroup.headers.map((header) => (
                  <th key={header.id} className="px-4 py-3 whitespace-nowrap font-medium">
                    {flexRender(header.column.columnDef.header, header.getContext())}
                  </th>
                ))}
              </tr>
            ))}
          </thead>
          <tbody className="divide-y divide-gray-100 dark:divide-gray-800">
            {isLoading ? (
              Array.from({ length: 5 }).map((_, i) => (
                <tr key={i} className="animate-pulse">
                  <td className="px-4 py-4"><div className="h-4 bg-gray-200 dark:bg-gray-800 rounded w-24"></div></td>
                  <td className="px-4 py-4"><div className="h-4 bg-gray-200 dark:bg-gray-800 rounded w-16"></div></td>
                  <td className="px-4 py-4"><div className="h-6 bg-gray-200 dark:bg-gray-800 rounded-full w-24"></div></td>
                  <td className="px-4 py-4"><div className="h-4 bg-gray-200 dark:bg-gray-800 rounded w-20"></div></td>
                  <td className="px-4 py-4"><div className="h-2 bg-gray-200 dark:bg-gray-800 rounded w-16"></div></td>
                </tr>
              ))
            ) : vehicles.length === 0 ? (
              <tr>
                <td colSpan={columns.length} className="px-4 py-8 text-center text-gray-500">
                  No vehicles found.
                </td>
              </tr>
            ) : (
              table.getRowModel().rows.map((row) => (
                <tr 
                  key={row.id} 
                  onClick={() => router.push(`/fleet/${row.original.id}`)}
                  className="hover:bg-gray-50 dark:hover:bg-gray-800/50 cursor-pointer transition-colors"
                >
                  {row.getVisibleCells().map((cell) => (
                    <td key={cell.id} className="px-4 py-3">
                      {flexRender(cell.column.columnDef.cell, cell.getContext())}
                    </td>
                  ))}
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {/* Pagination Controls */}
      <div className="flex items-center justify-between px-4 py-3 bg-white dark:bg-gray-900 border-t border-gray-200 dark:border-gray-800">
        <div className="flex-1 flex justify-between sm:hidden">
          <Button
            variant="outline"
            size="sm"
            onClick={() => onFiltersChange({ ...filters, page: Math.max(1, (filters.page || 1) - 1) })}
            disabled={(filters.page || 1) === 1}
          >
            Previous
          </Button>
          <Button
            variant="outline"
            size="sm"
            onClick={() => onFiltersChange({ ...filters, page: (filters.page || 1) + 1 })}
            disabled={(filters.page || 1) >= table.getPageCount()}
          >
            Next
          </Button>
        </div>
        <div className="hidden sm:flex-1 sm:flex sm:items-center sm:justify-between">
          <div>
            <p className="text-sm text-gray-700 dark:text-gray-400">
              Showing <span className="font-medium">{((filters.page || 1) - 1) * (filters.limit || 20) + (total > 0 ? 1 : 0)}</span> to <span className="font-medium">{Math.min((filters.page || 1) * (filters.limit || 20), total)}</span> of{' '}
              <span className="font-medium">{total}</span> vehicles
            </p>
          </div>
          <div>
            <nav className="relative z-0 inline-flex rounded-md shadow-sm -space-x-px" aria-label="Pagination">
              <Button
                variant="outline"
                className="rounded-r-none"
                onClick={() => onFiltersChange({ ...filters, page: Math.max(1, (filters.page || 1) - 1) })}
                disabled={(filters.page || 1) === 1}
              >
                Previous
              </Button>
              <Button
                variant="outline"
                className="rounded-l-none"
                onClick={() => onFiltersChange({ ...filters, page: (filters.page || 1) + 1 })}
                disabled={(filters.page || 1) >= table.getPageCount()}
              >
                Next
              </Button>
            </nav>
          </div>
        </div>
      </div>
    </div>
  );
}

