'use client';

import { useMemo } from 'react';
import { useRouter } from 'next/navigation';
import { Order, OrderFilters } from '@/types/orders';
import {
  flexRender,
  getCoreRowModel,
  useReactTable,
  ColumnDef,
} from '@tanstack/react-table';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Package, Truck, CheckCircle2, Clock, AlertTriangle, XCircle, CreditCard, Box } from 'lucide-react';

interface OrderTableProps {
  orders: Order[];
  total: number;
  isLoading: boolean;
  filters: OrderFilters;
  onFiltersChange: (filters: OrderFilters) => void;
}

const getStatusBadge = (status: Order['status']) => {
  switch (status) {
    case 'DELIVERED':
      return <Badge className="bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200"><CheckCircle2 className="mr-1 h-3 w-3" /> Delivered</Badge>;
    case 'IN_TRANSIT':
      return <Badge className="bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-200"><Truck className="mr-1 h-3 w-3" /> In Transit</Badge>;
    case 'PROCESSING':
    case 'READY_FOR_PICKUP':
      return <Badge className="bg-orange-100 text-orange-800 dark:bg-orange-900 dark:text-orange-200"><Package className="mr-1 h-3 w-3" /> {status.replace(/_/g, ' ')}</Badge>;
    case 'PENDING':
      return <Badge variant="secondary"><Clock className="mr-1 h-3 w-3" /> Pending</Badge>;
    case 'CANCELLED':
    case 'RETURNED':
      return <Badge variant="destructive"><XCircle className="mr-1 h-3 w-3" /> {status}</Badge>;
    default:
      return <Badge variant="outline">{status}</Badge>;
  }
};

const getPaymentBadge = (status: Order['paymentStatus']) => {
  switch (status) {
    case 'PAID': return <Badge variant="outline" className="border-green-200 text-green-700 bg-green-50"><CreditCard className="mr-1 h-3 w-3"/> Paid</Badge>;
    case 'UNPAID': return <Badge variant="outline" className="border-red-200 text-red-700 bg-red-50"><AlertTriangle className="mr-1 h-3 w-3"/> Unpaid</Badge>;
    case 'PARTIAL': return <Badge variant="outline" className="border-orange-200 text-orange-700 bg-orange-50">Partial</Badge>;
    default: return <Badge variant="secondary">{status}</Badge>;
  }
}

export function OrderTable({ orders, total, isLoading, filters, onFiltersChange }: OrderTableProps) {
  const router = useRouter();

  const columns = useMemo<ColumnDef<Order>[]>(
    () => [
      {
        accessorKey: 'orderNumber',
        header: 'Order #',
        cell: ({ row }) => (
          <div className="font-medium text-blue-600 dark:text-blue-400">
            {row.getValue('orderNumber')}
          </div>
        ),
      },
      {
        accessorKey: 'customer',
        header: 'Customer',
        cell: ({ row }) => (
          <div>
            <div className="font-medium text-gray-900 dark:text-white">{row.original.customer.name}</div>
            <div className="text-xs text-gray-500">{row.original.customer.companyName || row.original.customer.email}</div>
          </div>
        ),
      },
      {
        accessorKey: 'status',
        header: 'Status',
        cell: ({ row }) => getStatusBadge(row.getValue('status')),
      },
      {
        accessorKey: 'paymentStatus',
        header: 'Payment',
        cell: ({ row }) => getPaymentBadge(row.getValue('paymentStatus')),
      },
      {
        id: 'route',
        header: 'Route',
        cell: ({ row }) => (
          <div className="text-sm">
            <div className="text-gray-900 dark:text-gray-100">{row.original.origin.city} &rarr; {row.original.destination.city}</div>
          </div>
        )
      },
      {
        id: 'freight',
        header: 'Freight',
        cell: ({ row }) => (
          <div className="text-sm text-gray-500 flex items-center gap-1">
            <Box className="h-3 w-3" /> {row.original.totalWeight.toLocaleString()} kg
          </div>
        )
      }
    ],
    []
  );

  const table = useReactTable({
    data: orders,
    columns,
    getCoreRowModel: getCoreRowModel(),
    manualPagination: true,
    pageCount: Math.ceil(total / (filters.limit || 20)),
  });

  return (
    <div className="w-full">
      <div className="overflow-x-auto w-full">
        <table className="w-full text-sm text-left">
          <thead className="text-xs text-gray-500 uppercase bg-gray-50 dark:bg-gray-800 dark:text-gray-400 border-b border-gray-200 dark:border-gray-800">
            {table.getHeaderGroups().map((headerGroup) => (
              <tr key={headerGroup.id}>
                {headerGroup.headers.map((header) => (
                  <th key={header.id} className="px-4 py-3 whitespace-nowrap font-medium">
                    {flexRender(header.column.columnDef.header, header.getContext())}
                  </th>
                ))}
              </tr>
            ))}
          </thead>
          <tbody className="divide-y divide-gray-100 dark:divide-gray-800">
            {isLoading ? (
              Array.from({ length: 5 }).map((_, i) => (
                <tr key={i} className="animate-pulse">
                  <td className="px-4 py-4"><div className="h-4 bg-gray-200 dark:bg-gray-800 rounded w-24"></div></td>
                  <td className="px-4 py-4 space-y-2"><div className="h-4 bg-gray-200 dark:bg-gray-800 rounded w-32"></div><div className="h-3 bg-gray-200 dark:bg-gray-800 rounded w-24"></div></td>
                  <td className="px-4 py-4"><div className="h-6 bg-gray-200 dark:bg-gray-800 rounded-full w-24"></div></td>
                  <td className="px-4 py-4"><div className="h-6 bg-gray-200 dark:bg-gray-800 rounded-full w-20"></div></td>
                  <td className="px-4 py-4"><div className="h-4 bg-gray-200 dark:bg-gray-800 rounded w-32"></div></td>
                  <td className="px-4 py-4"><div className="h-4 bg-gray-200 dark:bg-gray-800 rounded w-16"></div></td>
                </tr>
              ))
            ) : orders.length === 0 ? (
              <tr>
                <td colSpan={columns.length} className="px-4 py-8 text-center text-gray-500">
                  No orders found.
                </td>
              </tr>
            ) : (
              table.getRowModel().rows.map((row) => (
                <tr 
                  key={row.id} 
                  onClick={() => router.push(`/orders/${row.original.id}`)}
                  className="hover:bg-gray-50 dark:hover:bg-gray-800/50 cursor-pointer transition-colors"
                >
                  {row.getVisibleCells().map((cell) => (
                    <td key={cell.id} className="px-4 py-3">
                      {flexRender(cell.column.columnDef.cell, cell.getContext())}
                    </td>
                  ))}
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {/* Pagination Controls */}
      <div className="flex items-center justify-between px-4 py-3 bg-white dark:bg-gray-900 border-t border-gray-200 dark:border-gray-800">
        <div className="flex-1 flex justify-between sm:hidden">
          <Button variant="outline" size="sm" onClick={() => onFiltersChange({ ...filters, page: Math.max(1, (filters.page || 1) - 1) })} disabled={(filters.page || 1) === 1}>Previous</Button>
          <Button variant="outline" size="sm" onClick={() => onFiltersChange({ ...filters, page: (filters.page || 1) + 1 })} disabled={(filters.page || 1) >= table.getPageCount()}>Next</Button>
        </div>
        <div className="hidden sm:flex-1 sm:flex sm:items-center sm:justify-between">
          <div>
            <p className="text-sm text-gray-700 dark:text-gray-400">
              Showing <span className="font-medium">{((filters.page || 1) - 1) * (filters.limit || 20) + (total > 0 ? 1 : 0)}</span> to <span className="font-medium">{Math.min((filters.page || 1) * (filters.limit || 20), total)}</span> of <span className="font-medium">{total}</span> orders
            </p>
          </div>
          <div>
            <nav className="relative z-0 inline-flex rounded-md shadow-sm -space-x-px" aria-label="Pagination">
              <Button variant="outline" className="rounded-r-none" onClick={() => onFiltersChange({ ...filters, page: Math.max(1, (filters.page || 1) - 1) })} disabled={(filters.page || 1) === 1}>Previous</Button>
              <Button variant="outline" className="rounded-l-none" onClick={() => onFiltersChange({ ...filters, page: (filters.page || 1) + 1 })} disabled={(filters.page || 1) >= table.getPageCount()}>Next</Button>
            </nav>
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { settingsService } from '@/services/settings';
import { OrganizationSettings as OrgSettings } from '@/types/settings';
import { useForm } from 'react-hook-form';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { 
  Select, 
  SelectContent, 
  SelectItem, 
  SelectTrigger, 
  SelectValue 
} from '@/components/ui/select';
import { Save, Loader2 } from 'lucide-react';
import { toast } from 'sonner';

export function OrganizationSettingsForm() {
  const queryClient = useQueryClient();

  const { data: initialData, isLoading } = useQuery({
    queryKey: ['settings', 'organization'],
    queryFn: () => settingsService.getOrganizationSettings(),
  });

  const { register, handleSubmit, setValue, watch, formState: { isDirty } } = useForm<OrgSettings>({
    values: initialData || {
      name: '',
      taxId: '',
      supportEmail: '',
      supportPhone: '',
      address: { street: '', city: '', state: '', country: '', postalCode: '' },
      localization: { timezone: 'UTC', currency: 'USD', dateFormat: 'MM/DD/YYYY', weightUnit: 'kg', distanceUnit: 'km' }
    }
  });

  const mutation = useMutation({
    mutationFn: (data: OrgSettings) => settingsService.updateOrganizationSettings(data),
    onSuccess: () => {
      toast.success('Organization settings updated');
      queryClient.invalidateQueries({ queryKey: ['settings', 'organization'] });
    },
    onError: () => toast.error('Failed to update settings'),
  });

  const onSubmit = (data: OrgSettings) => mutation.mutate(data);

  if (isLoading) {
    return (
      <div className="space-y-6 animate-pulse">
        <div className="h-64 bg-gray-200 dark:bg-gray-800 rounded-lg"></div>
      </div>
    );
  }

  return (
    <form onSubmit={handleSubmit(onSubmit)} className="space-y-8">

      <Card>
        <CardHeader>
          <CardTitle>Company Profile</CardTitle>
          <CardDescription>Legal entity details and support contact information.</CardDescription>
        </CardHeader>
        <CardContent className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="space-y-2">
            <Label>Organization Name</Label>
            <Input {...register('name')} />
          </div>
          <div className="space-y-2">
            <Label>Tax ID / VAT</Label>
            <Input {...register('taxId')} />
          </div>
          <div className="space-y-2">
            <Label>Support Email</Label>
            <Input type="email" {...register('supportEmail')} />
          </div>
          <div className="space-y-2">
            <Label>Support Phone</Label>
            <Input {...register('supportPhone')} />
          </div>
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle>Localization & Units</CardTitle>
          <CardDescription>System-wide defaults for formatting.</CardDescription>
        </CardHeader>
        <CardContent className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="space-y-2">
            <Label>Currency</Label>
            <Select value={watch('localization.currency')} onValueChange={(v) => setValue('localization.currency', (v as string), { shouldDirty: true })}>
              <SelectTrigger><SelectValue /></SelectTrigger>
              <SelectContent>
                <SelectItem value="USD">USD ($)</SelectItem>
                <SelectItem value="EUR">EUR (€)</SelectItem>
                <SelectItem value="GBP">GBP (£)</SelectItem>
              </SelectContent>
            </Select>
          </div>
          <div className="space-y-2">
            <Label>Timezone</Label>
            <Select value={watch('localization.timezone')} onValueChange={(v) => setValue('localization.timezone', (v as string), { shouldDirty: true })}>
              <SelectTrigger><SelectValue /></SelectTrigger>
              <SelectContent>
                <SelectItem value="UTC">UTC</SelectItem>
                <SelectItem value="America/New_York">Eastern Time (US)</SelectItem>
                <SelectItem value="Europe/London">London (GMT)</SelectItem>
              </SelectContent>
            </Select>
          </div>
          <div className="space-y-2">
            <Label>Weight Unit</Label>
            <Select value={watch('localization.weightUnit')} onValueChange={(v) => setValue('localization.weightUnit', (v as 'kg'|'lbs'), { shouldDirty: true })}>
              <SelectTrigger><SelectValue /></SelectTrigger>
              <SelectContent>
                <SelectItem value="kg">Kilograms (kg)</SelectItem>
                <SelectItem value="lbs">Pounds (lbs)</SelectItem>
              </SelectContent>
            </Select>
          </div>
          <div className="space-y-2">
            <Label>Distance Unit</Label>
            <Select value={watch('localization.distanceUnit')} onValueChange={(v) => setValue('localization.distanceUnit', (v as 'km'|'mi'), { shouldDirty: true })}>
              <SelectTrigger><SelectValue /></SelectTrigger>
              <SelectContent>
                <SelectItem value="km">Kilometers (km)</SelectItem>
                <SelectItem value="mi">Miles (mi)</SelectItem>
              </SelectContent>
            </Select>
          </div>
        </CardContent>
      </Card>

      <div className="flex justify-end">
        <Button type="submit" disabled={!isDirty || mutation.isPending}>
          {mutation.isPending ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <Save className="mr-2 h-4 w-4" />}
          {mutation.isPending ? 'Saving...' : 'Save Settings'}
        </Button>
      </div>

    </form>
  );
}

'use client';

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { settingsService } from '@/services/settings';
import { SecuritySettings as SecSettings } from '@/types/settings';
import { useForm, Controller } from 'react-hook-form';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Switch } from '@/components/ui/switch';
import { 
  Select, 
  SelectContent, 
  SelectItem, 
  SelectTrigger, 
  SelectValue 
} from '@/components/ui/select';
import { Save, Loader2, ShieldCheck, Smartphone } from 'lucide-react';
