interface TripTableProps {
  trips: Trip[];
  total: number;
  isLoading: boolean;
  filters: TripFilters;
  onFiltersChange: (filters: TripFilters) => void;
}

const getStatusBadge = (status: Trip['status']) => {
  switch (status) {
    case 'IN_TRANSIT':
      return <Badge className="bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-200"><Truck className="mr-1 h-3 w-3" /> In Transit</Badge>;
    case 'DELAYED':
      return <Badge className="bg-orange-100 text-orange-800 dark:bg-orange-900 dark:text-orange-200"><AlertTriangle className="mr-1 h-3 w-3" /> Delayed</Badge>;
    case 'COMPLETED':
      return <Badge className="bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200"><CheckCircle2 className="mr-1 h-3 w-3" /> Completed</Badge>;
    case 'DRAFT':
    case 'PLANNED':
      return <Badge variant="outline" className="text-gray-500"><Clock className="mr-1 h-3 w-3" /> {status.toLowerCase()}</Badge>;
    default:
      return <Badge variant="secondary">{status}</Badge>;
  }
};

export function TripTable({ trips, total, isLoading, filters, onFiltersChange }: TripTableProps) {
  const router = useRouter();

  const columns = useMemo<ColumnDef<Trip>[]>(
    () => [
      {
        accessorKey: 'trackingNumber',
        header: 'Tracking #',
        cell: ({ row }) => (
          <div className="font-medium text-blue-600 dark:text-blue-400">
            {row.getValue('trackingNumber')}
          </div>
        ),
      },
      {
        accessorKey: 'status',
        header: 'Status',
        cell: ({ row }) => getStatusBadge(row.getValue('status')),
      },
      {
        id: 'route',
        header: 'Route',
        cell: ({ row }) => (
          <div className="flex flex-col text-sm">
            <div className="flex items-center gap-1">
              <MapPin className="h-3 w-3 text-gray-400" />
              <span className="truncate max-w-[150px]" title={row.original.origin.name}>{row.original.origin.name}</span>
            </div>
            <div className="flex items-center gap-1 mt-1">
              <MapPin className="h-3 w-3 text-blue-500" />
              <span className="truncate max-w-[150px]" title={row.original.destination.name}>{row.original.destination.name}</span>
            </div>
          </div>
        ),
      },
      {
        accessorKey: 'plannedDeparture',
        header: 'Departure',
        cell: ({ row }) => (
          <span className="text-sm text-gray-500">
            {new Date(row.getValue('plannedDeparture')).toLocaleString()}
          </span>
        ),
      },
      {
        accessorKey: 'distance',
        header: 'Distance',
        cell: ({ row }) => (
          <span className="text-sm text-gray-500">
            {row.getValue<number>('distance')} mi
          </span>
        ),
      }
    ],
    []
  );

  const table = useReactTable({
    data: trips,
    columns,
    getCoreRowModel: getCoreRowModel(),
    manualPagination: true,
    pageCount: Math.ceil(total / (filters.limit || 20)),
  });

  return (
    <div className="w-full">
      <div className="overflow-x-auto w-full">
        <table className="w-full text-sm text-left">
          <thead className="text-xs text-gray-500 uppercase bg-gray-50 dark:bg-gray-800 dark:text-gray-400 border-b border-gray-200 dark:border-gray-800">
            {table.getHeaderGroups().map((headerGroup) => (
              <tr key={headerGroup.id}>
                {headerGroup.headers.map((header) => (
                  <th key={header.id} className="px-4 py-3 whitespace-nowrap font-medium">
                    {flexRender(header.column.columnDef.header, header.getContext())}
                  </th>
                ))}
              </tr>
            ))}
          </thead>
          <tbody className="divide-y divide-gray-100 dark:divide-gray-800">
            {isLoading ? (
              Array.from({ length: 5 }).map((_, i) => (
                <tr key={i} className="animate-pulse">
                  <td className="px-4 py-4"><div className="h-4 bg-gray-200 dark:bg-gray-800 rounded w-24"></div></td>
                  <td className="px-4 py-4"><div className="h-6 bg-gray-200 dark:bg-gray-800 rounded-full w-20"></div></td>
                  <td className="px-4 py-4">
                    <div className="h-3 bg-gray-200 dark:bg-gray-800 rounded w-32 mb-2"></div>
                    <div className="h-3 bg-gray-200 dark:bg-gray-800 rounded w-24"></div>
                  </td>
                  <td className="px-4 py-4"><div className="h-4 bg-gray-200 dark:bg-gray-800 rounded w-24"></div></td>
                  <td className="px-4 py-4"><div className="h-4 bg-gray-200 dark:bg-gray-800 rounded w-16"></div></td>
                </tr>
              ))
            ) : trips.length === 0 ? (
              <tr>
                <td colSpan={columns.length} className="px-4 py-8 text-center text-gray-500">
                  No trips found matching the criteria.
                </td>
              </tr>
            ) : (
              table.getRowModel().rows.map((row) => (
                <tr 
                  key={row.id} 
                  onClick={() => router.push(`/trips/${row.original.id}`)}
                  className="hover:bg-gray-50 dark:hover:bg-gray-800/50 cursor-pointer transition-colors"
                >
                  {row.getVisibleCells().map((cell) => (
                    <td key={cell.id} className="px-4 py-3">
