            variant="outline"
            size="sm"
            onClick={() => onFiltersChange({ ...filters, page: Math.max(1, (filters.page || 1) - 1) })}
            disabled={(filters.page || 1) === 1}
          >
            Previous
          </Button>
          <Button
            variant="outline"
            size="sm"
            onClick={() => onFiltersChange({ ...filters, page: (filters.page || 1) + 1 })}
            disabled={(filters.page || 1) >= table.getPageCount()}
          >
            Next
          </Button>
        </div>
        <div className="hidden sm:flex-1 sm:flex sm:items-center sm:justify-between">
          <div>
            <p className="text-sm text-gray-700 dark:text-gray-400">
              Showing <span className="font-medium">{((filters.page || 1) - 1) * (filters.limit || 20) + 1}</span> to <span className="font-medium">{Math.min((filters.page || 1) * (filters.limit || 20), total)}</span> of{' '}
              <span className="font-medium">{total}</span> results
            </p>
          </div>
          <div>
            <nav className="relative z-0 inline-flex rounded-md shadow-sm -space-x-px" aria-label="Pagination">
              <Button
                variant="outline"
                className="rounded-r-none"
                onClick={() => onFiltersChange({ ...filters, page: Math.max(1, (filters.page || 1) - 1) })}
                disabled={(filters.page || 1) === 1}
              >
                Previous
              </Button>
              <Button
                variant="outline"
                className="rounded-l-none"
                onClick={() => onFiltersChange({ ...filters, page: (filters.page || 1) + 1 })}
                disabled={(filters.page || 1) >= table.getPageCount()}
              >
                Next
              </Button>
            </nav>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import React, { useState } from 'react';
import {
  ColumnDef,
  flexRender,
  getCoreRowModel,
  useReactTable,
  getPaginationRowModel,
  getSortedRowModel,
  SortingState,
} from '@tanstack/react-table';

import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { Button } from '@/components/ui/button';
import { ChevronDown, ChevronUp, ChevronsUpDown } from 'lucide-react';

interface DataTableProps<TData, TValue> {
  columns: ColumnDef<TData, TValue>[];
  data: TData[];
}

export function DataTable<TData, TValue>({
  columns,
  data,
}: DataTableProps<TData, TValue>) {
  const [sorting, setSorting] = useState<SortingState>([]);

  const table = useReactTable({
    data,
    columns,
    getCoreRowModel: getCoreRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
    onSortingChange: setSorting,
    getSortedRowModel: getSortedRowModel(),
    state: {
      sorting,
    },
  });

  return (
    <div className="space-y-4">
      <div className="rounded-md border border-slate-800 overflow-hidden bg-slate-900/50 backdrop-blur">
        <Table>
          <TableHeader className="bg-slate-950/80 hover:bg-slate-950/80">
            {table.getHeaderGroups().map((headerGroup) => (
              <TableRow key={headerGroup.id} className="border-slate-800 hover:bg-transparent">
                {headerGroup.headers.map((header) => {
                  return (
                    <TableHead key={header.id} className="h-10 text-xs font-semibold text-slate-400 uppercase tracking-wider">
                      {header.isPlaceholder ? null : (
                        <div
                          {...{
                            className: header.column.getCanSort()
                              ? 'cursor-pointer select-none flex items-center gap-1 hover:text-slate-200 transition-colors'
                              : '',
                            onClick: header.column.getToggleSortingHandler(),
                          }}
                        >
                          {flexRender(
                            header.column.columnDef.header,
                            header.getContext()
                          )}
                          {{
                            asc: <ChevronUp className="h-3 w-3" />,
                            desc: <ChevronDown className="h-3 w-3" />,
                          }[header.column.getIsSorted() as string] ?? (
                            header.column.getCanSort() ? <ChevronsUpDown className="h-3 w-3 opacity-50" /> : null
                          )}
                        </div>
                      )}
                    </TableHead>
                  );
                })}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {table.getRowModel().rows?.length ? (
              table.getRowModel().rows.map((row) => (
                <TableRow
                  key={row.id}
                  data-state={row.getIsSelected() && "selected"}
                  className="border-slate-800 hover:bg-slate-800/50 transition-colors data-[state=selected]:bg-indigo-900/20"
                >
                  {row.getVisibleCells().map((cell) => (
                    <TableCell key={cell.id} className="py-2.5 text-sm text-slate-300">
                      {flexRender(cell.column.columnDef.cell, cell.getContext())}
                    </TableCell>
                  ))}
                </TableRow>
              ))
            ) : (
              <TableRow>
                <TableCell colSpan={columns.length} className="h-48 text-center">
                  <div className="flex flex-col items-center justify-center text-slate-500">
                    <div className="rounded-full bg-slate-800/50 p-4 mb-4 ring-1 ring-slate-700/50">
                      <svg
                        xmlns="http://www.w3.org/2000/svg"
                        width="24"
                        height="24"
                        viewBox="0 0 24 24"
                        fill="none"
                        stroke="currentColor"
                        strokeWidth="2"
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        className="h-8 w-8 text-slate-400 opacity-80"
                      >
                        <rect width="20" height="16" x="2" y="4" rx="2" />
                        <path d="m22 7-8.97 5.7a1.94 1.94 0 0 1-2.06 0L2 7" />
                      </svg>
                    </div>
                    <p className="text-base font-medium text-slate-300">No records found</p>
                    <p className="text-sm text-slate-500 mt-1 max-w-sm mx-auto">
                      There is currently no data to display in this view.
                    </p>
                  </div>
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </div>

      {/* Pagination Controls */}
      <div className="flex items-center justify-end space-x-2">
        <div className="flex-1 text-xs text-slate-500">
          Page {table.getState().pagination.pageIndex + 1} of{' '}
          {table.getPageCount()}
        </div>
        <Button
          variant="outline"
          size="sm"
          onClick={() => table.previousPage()}
          disabled={!table.getCanPreviousPage()}
          className="bg-slate-900 border-slate-700 hover:bg-slate-800 text-slate-300"
        >
          Previous
        </Button>
        <Button
          variant="outline"
          size="sm"
          onClick={() => table.nextPage()}
          disabled={!table.getCanNextPage()}
          className="bg-slate-900 border-slate-700 hover:bg-slate-800 text-slate-300"
        >
          Next
        </Button>
      </div>
    </div>
  );
}

'use client';

import { useForm, useFieldArray } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import * as z from 'zod';
import { useRouter } from 'next/navigation';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { wmsService } from '@/services/wms';
import { Warehouse } from '@/types/wms';
import { toast } from 'sonner';

import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Save, X, Plus, Trash2 } from 'lucide-react';
import { 
  Select, 
  SelectContent, 
  SelectItem, 
  SelectTrigger, 
  SelectValue 
} from '@/components/ui/select';

const addressSchema = z.object({
  street: z.string().min(1, 'Street is required'),
  city: z.string().min(1, 'City is required'),
  state: z.string().min(1, 'State is required'),
  postalCode: z.string().min(1, 'Postal Code is required'),
  country: z.string().min(1, 'Country is required'),
});

const warehouseFormSchema = z.object({
  code: z.string().min(3, 'Code is required'),
  name: z.string().min(1, 'Name is required'),
  type: z.enum(['DISTRIBUTION_CENTER', 'FULFILLMENT_CENTER', 'CROSS_DOCK', 'COLD_STORAGE', 'BONDED']),
  managerName: z.string().min(1, 'Manager Name required'),
  managerPhone: z.string().min(10, 'Valid phone required'),
  managerEmail: z.string().email('Invalid email'),
  operatingHours: z.string().min(1, 'Operating hours required'),
  address: addressSchema,
  capacity: z.object({
    totalPallets: z.number().min(0),
    totalSquareFeet: z.number().min(0)
  }),
  zones: z.array(z.object({
    name: z.string().min(1, 'Zone name required'),
    type: z.enum(['RACK', 'FLOOR', 'COLD', 'HAZMAT']),
    capacity: z.number().min(0)
  })).min(1, 'At least one zone is required')
});

export type WarehouseFormValues = z.infer<typeof warehouseFormSchema>;

interface WarehouseFormProps {
  initialData?: Warehouse;
  isEdit?: boolean;
}

export function WarehouseForm({ initialData, isEdit }: WarehouseFormProps) {
  const router = useRouter();
  const queryClient = useQueryClient();

  const { register, control, handleSubmit, setValue, watch, formState: { errors, isDirty } } = useForm<WarehouseFormValues>({
    resolver: zodResolver(warehouseFormSchema),
    defaultValues: initialData ? {
      code: initialData.code,
      name: initialData.name,
      type: initialData.type,
      managerName: initialData.managerName,
      managerPhone: initialData.managerPhone,
      managerEmail: initialData.managerEmail,
      operatingHours: initialData.operatingHours,
      address: initialData.address,
      capacity: {
        totalPallets: initialData.capacity.totalPallets,
        totalSquareFeet: initialData.capacity.totalSquareFeet,
      },
      zones: initialData.zones,
    } : {
      type: 'DISTRIBUTION_CENTER',
      capacity: { totalPallets: 1000, totalSquareFeet: 50000 },
      zones: [{ name: 'Zone A', type: 'RACK', capacity: 1000 }]
    }
  });

  const { fields, append, remove } = useFieldArray({
    control,
    name: "zones"
  });

  const mutation = useMutation({
    mutationFn: (data: any) => {
      // Auto-calculate available capacity (assuming 0 load for new)
      const payload = {
        ...data,
        capacity: {
          ...data.capacity,
          availablePallets: initialData ? initialData.capacity.availablePallets : data.capacity.totalPallets,
          utilizationPercentage: initialData ? initialData.capacity.utilizationPercentage : 0
        },
        zones: data.zones.map((z: any, i: number) => ({
          ...z,
          currentLoad: initialData && initialData.zones[i] ? initialData.zones[i].currentLoad : 0
        }))
      };

      if (isEdit && initialData) {
        return wmsService.updateWarehouse(initialData.id, payload);
      }
      const submissionData = {
        ...data,
        zones: data.zones.map((z: any) => ({ ...z, id: '' }))
      };
      return wmsService.createWarehouse(submissionData as any);
    },
    onSuccess: (data) => {
      toast.success(isEdit ? 'Facility updated' : 'Facility created successfully');
      queryClient.invalidateQueries({ queryKey: ['wms'] });
      router.push(`/wms/${data.id}`);
    },
    onError: (err: any) => {
      toast.error(err.normalizedMessage || 'Failed to save facility');
    }
  });

  const onSubmit = (data: WarehouseFormValues) => mutation.mutate(data);

  return (
    <form onSubmit={handleSubmit(onSubmit)} className="space-y-8">

      {/* Profile Info */}
      <div className="bg-white dark:bg-gray-900 p-6 rounded-lg shadow-sm border border-gray-200 dark:border-gray-800">
        <h3 className="text-lg font-medium text-gray-900 dark:text-white mb-4">Facility Identity</h3>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="space-y-2">
            <Label>Facility Code</Label>
            <Input {...register('code')} className="font-mono uppercase" placeholder="WH-XYZ-01" />
            {errors.code && <p className="text-sm text-red-500">{errors.code.message}</p>}
          </div>
          <div className="space-y-2">
            <Label>Facility Name</Label>
            <Input {...register('name')} />
          </div>
          <div className="space-y-2">
            <Label>Facility Type</Label>
            <Select value={watch('type')} onValueChange={(v: any) => setValue('type', v, { shouldDirty: true })}>
              <SelectTrigger><SelectValue placeholder="Select type" /></SelectTrigger>
              <SelectContent>
                <SelectItem value="DISTRIBUTION_CENTER">Distribution Center</SelectItem>
                <SelectItem value="FULFILLMENT_CENTER">Fulfillment Center</SelectItem>
                <SelectItem value="CROSS_DOCK">Cross Dock</SelectItem>
                <SelectItem value="COLD_STORAGE">Cold Storage</SelectItem>
                <SelectItem value="BONDED">Bonded</SelectItem>
              </SelectContent>
            </Select>
          </div>
          <div className="space-y-2">
            <Label>Operating Hours</Label>
            <Input {...register('operatingHours')} placeholder="e.g. 24/7 or 08:00 - 18:00" />
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* Address */}
        <div className="bg-white dark:bg-gray-900 p-6 rounded-lg shadow-sm border border-gray-200 dark:border-gray-800">
          <h3 className="text-lg font-medium text-gray-900 dark:text-white mb-4">Location Address</h3>
          <div className="space-y-4">
            <div className="space-y-2">
              <Label>Street Address</Label>
              <Input {...register('address.street')} />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2"><Label>City</Label><Input {...register('address.city')} /></div>
              <div className="space-y-2"><Label>State</Label><Input {...register('address.state')} /></div>
              <div className="space-y-2"><Label>ZIP Code</Label><Input {...register('address.postalCode')} /></div>
              <div className="space-y-2"><Label>Country</Label><Input {...register('address.country')} defaultValue="USA" /></div>
            </div>
          </div>
        </div>

        {/* Management & Capacity */}
        <div className="bg-white dark:bg-gray-900 p-6 rounded-lg shadow-sm border border-gray-200 dark:border-gray-800 flex flex-col gap-6">
          <div>
            <h3 className="text-lg font-medium text-gray-900 dark:text-white mb-4">Site Manager</h3>
            <div className="space-y-4">
              <div className="space-y-2"><Label>Name</Label><Input {...register('managerName')} /></div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2"><Label>Phone</Label><Input type="tel" {...register('managerPhone')} /></div>
                <div className="space-y-2"><Label>Email</Label><Input type="email" {...register('managerEmail')} /></div>
              </div>
            </div>
          </div>
          <div className="border-t border-gray-100 dark:border-gray-800 pt-6">
            <h3 className="text-lg font-medium text-gray-900 dark:text-white mb-4">Base Capacity</h3>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>Total Sq Ft</Label>
                <Input type="number" {...register('capacity.totalSquareFeet', { valueAsNumber: true })} />
              </div>
              <div className="space-y-2">
                <Label>Total Pallet Positions</Label>
                <Input type="number" {...register('capacity.totalPallets', { valueAsNumber: true })} />
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Zones Array */}
      <div className="bg-white dark:bg-gray-900 p-6 rounded-lg shadow-sm border border-gray-200 dark:border-gray-800">
        <div className="flex justify-between items-center mb-4">
          <h3 className="text-lg font-medium text-gray-900 dark:text-white">Warehouse Zones</h3>
          <Button type="button" variant="outline" size="sm" onClick={() => append({ name: '', type: 'RACK', capacity: 100 })}>
            <Plus className="mr-2 h-4 w-4" /> Add Zone
          </Button>
        </div>
        <div className="space-y-4">
          {fields.map((field, index) => (
            <div key={field.id} className="p-4 border border-gray-200 dark:border-gray-700 rounded-lg relative">
              {fields.length > 1 && (
                <Button type="button" variant="ghost" size="icon" className="absolute right-2 top-2 text-red-500" onClick={() => remove(index)}>
                  <Trash2 className="h-4 w-4" />
                </Button>
              )}
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4 pr-8">
                <div className="space-y-2"><Label>Zone Name / ID</Label><Input {...register(`zones.${index}.name` as const)} placeholder="e.g. Aisle 1" /></div>
                <div className="space-y-2">
                  <Label>Zone Type</Label>
                  <Select value={watch(`zones.${index}.type` as const)} onValueChange={(v: any) => setValue(`zones.${index}.type` as const, v, { shouldDirty: true })}>
                    <SelectTrigger><SelectValue placeholder="Select type" /></SelectTrigger>
                    <SelectContent>
                      <SelectItem value="RACK">Standard Racking</SelectItem>
                      <SelectItem value="FLOOR">Floor Storage</SelectItem>
                      <SelectItem value="COLD">Cold Storage</SelectItem>
                      <SelectItem value="HAZMAT">HAZMAT</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-2"><Label>Capacity (Pallets)</Label><Input type="number" {...register(`zones.${index}.capacity` as const, { valueAsNumber: true })} /></div>
              </div>
            </div>
          ))}
        </div>
      </div>

      <div className="flex justify-end gap-4 pt-4">
        <Button type="button" variant="outline" onClick={() => router.back()}>
          <X className="mr-2 h-4 w-4" /> Cancel
        </Button>
        <Button type="submit" disabled={!isDirty || mutation.isPending}>
          <Save className="mr-2 h-4 w-4" /> {mutation.isPending ? 'Saving...' : 'Save Facility'}
        </Button>
      </div>
    </form>
  );
}

'use client';

import { useMemo } from 'react';
import { useRouter } from 'next/navigation';
import { Warehouse, WMSFilters } from '@/types/wms';
import {
  flexRender,
  getCoreRowModel,
  useReactTable,
  ColumnDef,
} from '@tanstack/react-table';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Building, CheckCircle2, AlertTriangle, AlertCircle, XCircle } from 'lucide-react';

interface WarehouseTableProps {
  warehouses: Warehouse[];
  total: number;
  isLoading: boolean;
  filters: WMSFilters;
  onFiltersChange: (filters: WMSFilters) => void;
}

const getStatusBadge = (status: Warehouse['status']) => {
  switch (status) {
    case 'OPERATIONAL':
      return <Badge className="bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200"><CheckCircle2 className="mr-1 h-3 w-3" /> Operational</Badge>;
    case 'AT_CAPACITY':
      return <Badge variant="destructive"><AlertTriangle className="mr-1 h-3 w-3" /> At Capacity</Badge>;
    case 'MAINTENANCE':
      return <Badge className="bg-orange-100 text-orange-800 dark:bg-orange-900 dark:text-orange-200"><AlertCircle className="mr-1 h-3 w-3" /> Maintenance</Badge>;
    case 'CLOSED':
      return <Badge variant="secondary"><XCircle className="mr-1 h-3 w-3" /> Closed</Badge>;
    default:
      return <Badge variant="outline">{status}</Badge>;
  }
};

export function WarehouseTable({ warehouses, total, isLoading, filters, onFiltersChange }: WarehouseTableProps) {
  const router = useRouter();

  const columns = useMemo<ColumnDef<Warehouse>[]>(
    () => [
      {
        accessorKey: 'code',
        header: 'Code',
        cell: ({ row }) => (
          <div className="font-mono text-sm font-semibold text-blue-600 dark:text-blue-400">
            {row.getValue('code')}
          </div>
        ),
      },
      {
        accessorKey: 'name',
        header: 'Facility',
        cell: ({ row }) => (
          <div>
            <div className="font-medium text-gray-900 dark:text-white">{row.original.name}</div>
            <div className="text-xs text-gray-500">{row.original.type.replace(/_/g, ' ')}</div>
          </div>
        ),
      },
      {
        accessorKey: 'status',
        header: 'Status',
        cell: ({ row }) => getStatusBadge(row.getValue('status')),
      },
      {
        id: 'location',
        header: 'Location',
        cell: ({ row }) => <span className="text-sm text-gray-600 dark:text-gray-400">{row.original.address.city}, {row.original.address.state}</span>,
      },
      {
        id: 'utilization',
        header: 'Capacity (Pallets)',
        cell: ({ row }) => {
          const util = row.original.capacity.utilizationPercentage;
          const color = util > 90 ? 'bg-red-500' : util > 75 ? 'bg-orange-500' : 'bg-green-500';
          return (
            <div className="flex flex-col gap-1 w-32">
              <div className="flex justify-between text-xs">
                <span className="font-medium text-gray-700 dark:text-gray-300">{row.original.capacity.availablePallets.toLocaleString()} free</span>
                <span className="text-gray-500">{util}%</span>
              </div>
              <div className="w-full h-1.5 bg-gray-200 dark:bg-gray-700 rounded-full overflow-hidden">
                <div className={`h-full ${color}`} style={{ width: `${util}%` }}></div>
              </div>
            </div>
          );
        },
      }
    ],
    []
  );

  const table = useReactTable({
    data: warehouses,
    columns,
    getCoreRowModel: getCoreRowModel(),
    manualPagination: true,
    pageCount: Math.ceil(total / (filters.limit || 20)),
  });

  return (
    <div className="w-full">
      <div className="overflow-x-auto w-full">
        <table className="w-full text-sm text-left">
          <thead className="text-xs text-gray-500 uppercase bg-gray-50 dark:bg-gray-800 dark:text-gray-400 border-b border-gray-200 dark:border-gray-800">
            {table.getHeaderGroups().map((headerGroup) => (
              <tr key={headerGroup.id}>
                {headerGroup.headers.map((header) => (
                  <th key={header.id} className="px-4 py-3 whitespace-nowrap font-medium">
                    {flexRender(header.column.columnDef.header, header.getContext())}
                  </th>
                ))}
              </tr>
            ))}
          </thead>
          <tbody className="divide-y divide-gray-100 dark:divide-gray-800">
            {isLoading ? (
              Array.from({ length: 5 }).map((_, i) => (
                <tr key={i} className="animate-pulse">
                  <td className="px-4 py-4"><div className="h-4 bg-gray-200 dark:bg-gray-800 rounded w-16"></div></td>
                  <td className="px-4 py-4 space-y-2"><div className="h-4 bg-gray-200 dark:bg-gray-800 rounded w-32"></div><div className="h-3 bg-gray-200 dark:bg-gray-800 rounded w-24"></div></td>
                  <td className="px-4 py-4"><div className="h-6 bg-gray-200 dark:bg-gray-800 rounded-full w-24"></div></td>
                  <td className="px-4 py-4"><div className="h-4 bg-gray-200 dark:bg-gray-800 rounded w-24"></div></td>
                  <td className="px-4 py-4 space-y-1"><div className="flex justify-between w-32"><div className="h-3 bg-gray-200 dark:bg-gray-800 rounded w-12"></div><div className="h-3 bg-gray-200 dark:bg-gray-800 rounded w-8"></div></div><div className="h-1.5 bg-gray-200 dark:bg-gray-800 rounded w-32"></div></td>
                </tr>
              ))
            ) : warehouses.length === 0 ? (
              <tr>
                <td colSpan={columns.length} className="px-4 py-8 text-center text-gray-500">
                  No facilities found.
                </td>
              </tr>
            ) : (
              table.getRowModel().rows.map((row) => (
                <tr 
                  key={row.id} 
                  onClick={() => router.push(`/wms/${row.original.id}`)}
                  className="hover:bg-gray-50 dark:hover:bg-gray-800/50 cursor-pointer transition-colors"
                >
                  {row.getVisibleCells().map((cell) => (
                    <td key={cell.id} className="px-4 py-3">
                      {flexRender(cell.column.columnDef.cell, cell.getContext())}
                    </td>
                  ))}
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {/* Pagination Controls */}
      <div className="flex items-center justify-between px-4 py-3 bg-white dark:bg-gray-900 border-t border-gray-200 dark:border-gray-800">
        <div className="flex-1 flex justify-between sm:hidden">
          <Button variant="outline" size="sm" onClick={() => onFiltersChange({ ...filters, page: Math.max(1, (filters.page || 1) - 1) })} disabled={(filters.page || 1) === 1}>Previous</Button>
          <Button variant="outline" size="sm" onClick={() => onFiltersChange({ ...filters, page: (filters.page || 1) + 1 })} disabled={(filters.page || 1) >= table.getPageCount()}>Next</Button>
        </div>
        <div className="hidden sm:flex-1 sm:flex sm:items-center sm:justify-between">
          <div>
            <p className="text-sm text-gray-700 dark:text-gray-400">
              Showing <span className="font-medium">{((filters.page || 1) - 1) * (filters.limit || 20) + (total > 0 ? 1 : 0)}</span> to <span className="font-medium">{Math.min((filters.page || 1) * (filters.limit || 20), total)}</span> of <span className="font-medium">{total}</span> facilities
            </p>
          </div>
          <div>
            <nav className="relative z-0 inline-flex rounded-md shadow-sm -space-x-px" aria-label="Pagination">
              <Button variant="outline" className="rounded-r-none" onClick={() => onFiltersChange({ ...filters, page: Math.max(1, (filters.page || 1) - 1) })} disabled={(filters.page || 1) === 1}>Previous</Button>
              <Button variant="outline" className="rounded-l-none" onClick={() => onFiltersChange({ ...filters, page: (filters.page || 1) + 1 })} disabled={(filters.page || 1) >= table.getPageCount()}>Next</Button>
            </nav>
          </div>
        </div>
      </div>
    </div>
  );
}
